const assert = require('node:assert/strict');
const { Ledger } = require('../.build/ledger');
const { PaymentService } = require('../.build/service');
const { Transient } = require('../.build/transport');

// Builds a service whose acknowledge() records every receipt it is given and then
// runs an optional hook (which may throw). Ledger.apply calls are counted too.
function harness(onAck) {
  const ledger = new Ledger();
  const acks = [];
  let applyCalls = 0;
  const realApply = ledger.apply.bind(ledger);
  ledger.apply = (...args) => { applyCalls++; return realApply(...args); };
  const transport = {
    acknowledge: async receipt => {
      acks.push(receipt);
      if (onAck) await onAck(receipt, acks.length);
    },
  };
  return {
    ledger, acks, service: new PaymentService(ledger, transport),
    applyCalls: () => applyCalls,
  };
}

const isError = (message) => e => e instanceof Error && e.message === message;
const tick = () => new Promise(resolve => setImmediate(resolve));

const tests = {
  'repeat with equal amount returns original receipt and debits once': async () => {
    const { ledger, service } = harness();
    const first = await service.pay('t1', 'k1', 500);
    const second = await service.pay('t1', 'k1', 500);
    assert.equal(second, first);
    assert.equal(ledger.entries.length, 1);
  },

  'concurrent equal calls debit once and all get the original receipt': async () => {
    const { ledger, service } = harness(tick);
    const results = await Promise.all([1, 2, 3, 4, 5].map(() => service.pay('t1', 'k1', 500)));
    assert.equal(ledger.entries.length, 1);
    for (const r of results) assert.equal(r, results[0]);
  },

  'reuse with another amount throws key conflict without a debit': async () => {
    const { ledger, service } = harness();
    const first = await service.pay('t1', 'k1', 500);
    await assert.rejects(service.pay('t1', 'k1', 501), isError('key conflict'));
    assert.equal(ledger.entries.length, 1);
    assert.equal(ledger.entries[0], first);
  },

  'concurrent reuse with another amount: one debit, one key conflict': async () => {
    const { ledger, service } = harness(tick);
    const results = await Promise.allSettled([service.pay('t1', 'k1', 500), service.pay('t1', 'k1', 999)]);
    const fulfilled = results.filter(r => r.status === 'fulfilled');
    const rejected = results.filter(r => r.status === 'rejected');
    assert.equal(fulfilled.length, 1);
    assert.equal(rejected.length, 1);
    assert.ok(isError('key conflict')(rejected[0].reason));
    assert.equal(ledger.entries.length, 1);
  },

  'scope is tenant and key, not their concatenation': async () => {
    const { ledger, service } = harness();
    await service.pay('ab', 'c', 1);
    await service.pay('a', 'bc', 2);
    await service.pay('t2', 'k', 7);
    await service.pay('t1', 'k', 7);
    assert.equal(ledger.entries.length, 4);
  },

  'Transient from acknowledge is retried with the same receipt; debit happens once': async () => {
    const { ledger, acks, service, applyCalls } = harness((_, n) => { if (n < 3) throw new Transient('busy'); });
    const receipt = await service.pay('t', 'k', 9, 3);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks.length, 3);
    for (const a of acks) assert.equal(a, receipt);
    assert.equal(applyCalls(), 1);
  },

  'exhausted retries rethrow the final Transient': async () => {
    const thrown = [];
    const { ledger, acks, service } = harness(async () => {
      const e = new Transient(`busy ${thrown.length + 1}`);
      thrown.push(e);
      throw e;
    });
    await assert.rejects(service.pay('t', 'k', 9, 4), e => e === thrown[3]);
    assert.equal(acks.length, 4);
    assert.equal(ledger.entries.length, 1);
  },

  'non-Transient acknowledge error is not retried': async () => {
    const boom = new Error('boom');
    const { ledger, acks, service } = harness(async () => { throw boom; });
    await assert.rejects(service.pay('t', 'k', 9, 5), e => e === boom);
    assert.equal(acks.length, 1);
    assert.equal(ledger.entries.length, 1);
  },

  'Transient from ledger.apply after commit is retried without a second debit': async () => {
    const ledger = new Ledger();
    const realApply = ledger.apply.bind(ledger);
    let calls = 0;
    ledger.apply = async (...args) => {
      const receipt = await realApply(...args);
      if (calls++ === 0) throw new Transient('response lost');
      return receipt;
    };
    const acks = [];
    const service = new PaymentService(ledger, { acknowledge: async r => { acks.push(r); } });
    const receipt = await service.pay('t', 'k', 9);
    assert.equal(ledger.entries.length, 1);
    assert.equal(acks.length, 1);
    assert.equal(acks[0], receipt);
  },

  'non-Transient from ledger.apply is not retried': async () => {
    const boom = new Error('ledger down');
    const ledger = new Ledger();
    let calls = 0;
    ledger.apply = async () => { calls++; throw boom; };
    const service = new PaymentService(ledger, { acknowledge: async () => {} });
    await assert.rejects(service.pay('t', 'k', 9, 5), e => e === boom);
    assert.equal(calls, 1);
  },

  'attempts=1 makes exactly one try': async () => {
    const { acks, service } = harness(async () => { throw new Transient('busy'); });
    await assert.rejects(service.pay('t', 'k', 9, 1), e => e instanceof Transient);
    assert.equal(acks.length, 1);
  },

  'default attempts is 3 total tries': async () => {
    const { acks, service } = harness(async () => { throw new Transient('busy'); });
    await assert.rejects(service.pay('t', 'k', 9), e => e instanceof Transient);
    assert.equal(acks.length, 3);
  },

  'attempts=5 is accepted and bounds the tries': async () => {
    const { acks, service } = harness(async () => { throw new Transient('busy'); });
    await assert.rejects(service.pay('t', 'k', 9, 5), e => e instanceof Transient);
    assert.equal(acks.length, 5);
  },

  'invalid tenant/key/cents throw invalid payment before any ledger or transport action': async () => {
    const cases = [
      ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], ['t', undefined, 1], [null, 'k', 1],
      ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN], ['t', 'k', Infinity],
    ];
    for (const [t, k, c] of cases) {
      const { ledger, acks, service, applyCalls } = harness();
      await assert.rejects(service.pay(t, k, c), isError('invalid payment'), JSON.stringify([t, k, c]));
      assert.equal(applyCalls(), 0);
      assert.equal(acks.length, 0);
      assert.equal(ledger.entries.length, 0);
    }
  },

  'invalid attempts throw invalid payment before any ledger or transport action': async () => {
    for (const attempts of [0, -1, 6, 1.5, '3', NaN, Infinity, null]) {
      const { ledger, acks, service, applyCalls } = harness();
      await assert.rejects(service.pay('t', 'k', 9, attempts), isError('invalid payment'), String(attempts));
      assert.equal(applyCalls(), 0);
      assert.equal(acks.length, 0);
      assert.equal(ledger.entries.length, 0);
    }
  },

  'Ledger.apply rejects reuse with another amount without a debit': async () => {
    const ledger = new Ledger();
    await ledger.apply('t', 'k', 5);
    await assert.rejects(ledger.apply('t', 'k', 6), isError('key conflict'));
    assert.equal(ledger.entries.length, 1);
  },
};

(async () => {
  const failures = [];
  for (const [name, fn] of Object.entries(tests)) {
    try { await fn(); console.log(`ok   - ${name}`); }
    catch (error) { failures.push(name); console.log(`FAIL - ${name}\n       ${String(error && error.message).split('\n')[0]}`); }
  }
  if (failures.length) { console.log(`\n${failures.length} of ${Object.keys(tests).length} failed`); process.exitCode = 1; }
  else console.log(`\nall ${Object.keys(tests).length} passed`);
})();

